def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()

def fill(text,context):
    def replace(match):
        key=match.group(1)
        if key not in context:raise ValueError('Missing explicit source identity '+key)
        return str(context[key])
    result=re.sub(r'@@([A-Z0-9_]+)@@',replace,text)
    if re.search(r'@@[A-Z0-9_]+@@',result):raise ValueError('Unexpanded source identity')
    return result

def function_span(source,name):
    matches=list(re.finditer(r'^def '+re.escape(name)+r'\(',source,re.M))
    if len(matches)!=1:raise ValueError('Expected one complete top-level function '+name)
    start=matches[0].start()
    following=re.search(r'\ndef ',source[start+1:])
    end=len(source) if following is None else start+1+following.start()
    return start,end

def build(original,context=None):
    if digest(original)!=ORIGINAL_SHA256:
        raise ValueError('Keep the complete immutable original transfer source')
    context=dict(DEFAULT_CONTEXT if context is None else context)
    result=original
    for operation in OPERATIONS:
        replacement=fill(operation['new'],context)
        if 'function' in operation:
            left,right=function_span(result,operation['function'])
            if digest(result[left:right])!=operation['old_sha256']:
                raise ValueError('The entire original function body changed: '+operation['function'])
            result=result[:left]+replacement+result[right:]
        else:
            old=operation['old']
            if result.count(old)!=operation['count']:raise ValueError('An exact source replacement changed cardinality')
            result=result.replace(old,replacement)
    if len(result.encode())>=100000 or digest(result)!=EXPECTED_SHA256:
        raise ValueError('The complete rebuilt transfer source differs from its locked output')
    ast.parse(result);compile(result,'transfer_material_envelope_to_frequency_refinement.py','exec')
    return result

